from django.conf import settings
from django.db import models


class Notification(models.Model):
    """One row per (event, kind, recipient_user). Generated by the daily
    cron management command. Each staff user gets their own copy with
    independent read / dismissed state.

    The natural-key UniqueConstraint enforces idempotency: re-running
    the cron on the same day uses ``update_or_create`` and does not
    produce duplicates or re-send emails.
    """

    KIND_VACCINATION_DUE = 'vaccination_due'
    KIND_PET_ARRIVING_TODAY = 'pet_arriving_today'
    KIND_PET_ARRIVING_TOMORROW = 'pet_arriving_tomorrow'
    KIND_PET_EGRESS_TODAY = 'pet_egress_today'
    KIND_PET_EGRESS_TOMORROW = 'pet_egress_tomorrow'
    KIND_PET_BIRTHDAY = 'pet_birthday'
    KIND_DEWORMING_INTERNAL_DUE = 'deworming_internal_due'
    KIND_DEWORMING_EXTERNAL_DUE = 'deworming_external_due'

    KIND_CHOICES = [
        (KIND_VACCINATION_DUE, 'Vaccination due'),
        (KIND_PET_ARRIVING_TODAY, 'Pet arriving today'),
        (KIND_PET_ARRIVING_TOMORROW, 'Pet arriving tomorrow'),
        (KIND_PET_EGRESS_TODAY, 'Pet egress today'),
        (KIND_PET_EGRESS_TOMORROW, 'Pet egress tomorrow'),
        (KIND_PET_BIRTHDAY, 'Pet birthday'),
        (KIND_DEWORMING_INTERNAL_DUE, 'Internal deworming due'),
        (KIND_DEWORMING_EXTERNAL_DUE, 'External deworming due'),
    ]

    # Mapping kind → template scope. Kinds not in this map have no
    # forward-to-owner buttons (internal-only operational reminders).
    KIND_TO_SCOPE = {
        KIND_VACCINATION_DUE: 'treatment_due',
        KIND_DEWORMING_INTERNAL_DUE: 'treatment_due',
        KIND_DEWORMING_EXTERNAL_DUE: 'treatment_due',
        KIND_PET_BIRTHDAY: 'pet_birthday',
    }

    kind = models.CharField(max_length=40, choices=KIND_CHOICES)
    pet = models.ForeignKey('pets.Pet', on_delete=models.CASCADE, related_name='notifications')
    schedule = models.ForeignKey(
        'pets.Schedule', null=True, blank=True, on_delete=models.CASCADE,
        related_name='notifications',
        help_text="Set for arrival / egress kinds; NULL otherwise.",
    )
    vaccination = models.ForeignKey(
        'pets.Vaccination', null=True, blank=True, on_delete=models.CASCADE,
        related_name='notifications',
        help_text="Set for vaccination_due; NULL otherwise.",
    )
    event_date = models.DateField(
        help_text="The day the event happens (arrival, egress, birthday, due date)."
    )
    recipient_user = models.ForeignKey(
        settings.AUTH_USER_MODEL, on_delete=models.CASCADE, related_name='notifications',
    )
    payload = models.JSONField(
        default=dict,
        help_text="Per-kind extras (vax_type, deworming side, time slot, …).",
    )
    created_at = models.DateTimeField(auto_now_add=True)
    read_at = models.DateTimeField(null=True, blank=True)
    dismissed_at = models.DateTimeField(null=True, blank=True)
    forwarded_at = models.DateTimeField(
        null=True, blank=True,
        help_text=(
            "First time a staff member triggered an owner-forward "
            "(email or WhatsApp) action on this row. Set once on first "
            "click; subsequent clicks are no-ops so the timestamp "
            "stays stable."
        ),
    )

    class Meta:
        constraints = [
            models.UniqueConstraint(
                fields=['kind', 'pet', 'event_date', 'recipient_user',
                        'schedule', 'vaccination'],
                name='notifications_natural_key',
            ),
        ]
        indexes = [
            models.Index(fields=['recipient_user', 'dismissed_at']),
            models.Index(fields=['recipient_user', 'read_at']),
        ]
        ordering = ['-event_date', '-created_at']

    def __str__(self):
        return f"{self.kind} for {self.pet_id} on {self.event_date} → user {self.recipient_user_id}"

    @property
    def template_scope(self):
        """The NotificationTemplate scope this kind maps to, or ``None``
        for internal-only kinds (no forward-to-owner buttons).
        """
        return self.KIND_TO_SCOPE.get(self.kind)


class NotificationPreference(models.Model):
    """Per-user delivery toggles. One row per user, materialised on
    first read.
    """

    user = models.OneToOneField(
        settings.AUTH_USER_MODEL,
        on_delete=models.CASCADE,
        related_name='notification_preference',
    )
    email_enabled = models.BooleanField(default=True)
    updated_at = models.DateTimeField(auto_now=True)

    def __str__(self):
        return f"NotificationPreference(user={self.user_id}, email_enabled={self.email_enabled})"


class NotificationTemplate(models.Model):
    """Per-nursery message templates used to fill the forward-to-owner
    affordance on the matching notification kinds.

    The catalog of scopes is fixed in v1: ``treatment_due`` (used by
    vaccination + deworming kinds) and ``pet_birthday``. Each row has
    three text fields, one per channel; an empty field falls back to
    the localised default in the user's preferred language.
    """

    SCOPE_TREATMENT_DUE = 'treatment_due'
    SCOPE_PET_BIRTHDAY = 'pet_birthday'

    SCOPE_CHOICES = [
        (SCOPE_TREATMENT_DUE, 'Treatment due (vaccination / deworming)'),
        (SCOPE_PET_BIRTHDAY, 'Pet birthday'),
    ]

    scope = models.CharField(max_length=40, choices=SCOPE_CHOICES, unique=True)
    email_subject = models.TextField(blank=True)
    email_body = models.TextField(blank=True)
    whatsapp_text = models.TextField(blank=True)
    updated_at = models.DateTimeField(auto_now=True)

    class Meta:
        ordering = ['scope']

    def __str__(self):
        return f"NotificationTemplate({self.scope})"
